#![no_implicit_prelude]
unitary fn keep(q:Q<Bit>)->Q<Bit>{q}
meaning I:Bit=reference(keep);
unitary fn choose[const U:Op<Bit>](s:Q<Bit>,q:Q<Bit>)->(Q<Bit>,Q<Bit>)
    requires Applicable(U),Controllable(U) {
    qmatch(s,q){0=>keep,1=>checked_op(U,I)}
}
unitary fn relay[const W:Op<Bit>](s:Q<Bit>,q:Q<Bit>)->(Q<Bit>,Q<Bit>)
    requires Applicable(W),Controllable(W) {choose[W](s,q)}
pub unitary fn route(s:Q<Bit>,q:Q<Bit>)->(Q<Bit>,Q<Bit>){
    let (s,q)=relay[keep](s,q);
    relay[keep](s,q)
}

#![no_implicit_prelude]
unitary fn keep(q:Q<Bit>)->Q<Bit>{q}
meaning I:Bit=reference(keep);
unitary fn choose[const U:Op<Bit>](s:Q<Bit>,q:Q<Bit>)->(Q<Bit>,Q<Bit>)
    requires Applicable(U),Controllable(U) {
    qmatch(s,q){0=>keep,1=>checked_op(U,I)}
}
unitary fn relay[const W:Op<Bit>,const V:Op<Bit>](s:Q<Bit>,q:Q<Bit>)->(Q<Bit>,Q<Bit>)
    requires Applicable(W),Controllable(W),Applicable(V),Controllable(V) {
    choose[then_op(W,W)](s,q)
}
pub unitary fn route(s:Q<Bit>,q:Q<Bit>)->(Q<Bit>,Q<Bit>){
    relay[keep,keep](s,q)
}

#![no_implicit_prelude]
unitary fn keep(q:Q<Bit>)->Q<Bit>{q}
unitary fn accept[const U:Op<Bit>](q:Q<Bit>)->Q<Bit>
    requires Applicable(U),Adjointable(U),Controllable(U){U(q)}
unitary fn provider[const count:Nat,const action:Op<Bit>,const unused:Op<Bit>](q:Q<Bit>)->Q<Bit>
    requires Applicable(action),Adjointable(action),Controllable(action),
             Applicable(unused),Adjointable(unused),Controllable(unused){action(q)}
unitary fn relay[const seed:Nat,const W:Op<Bit>](q:Q<Bit>)->Q<Bit>
    requires Applicable(W),Adjointable(W),Controllable(W){
    accept[provider[seed,then_op(W,power(W,0)),W]](q)
}
pub unitary fn route(q:Q<Bit>)->Q<Bit>{relay[0,keep](q)}
